package com.example.melonstools.data;
import com.example.melonstools.department.DepartmentPolicy;import com.google.gson.*;import net.minecraft.nbt.*;import net.minecraft.server.level.*;import net.minecraft.world.level.saveddata.SavedData;import java.util.*;
/** Phase 4-C audited reinforcement requests. */
public class ReinforcementSavedData extends SavedData{public static final String DATA_NAME="melon_reinforcements";public static final String OPEN="open",CLAIMED="claimed",ARRIVED="arrived",RESOLVED="resolved",CANCELLED="cancelled";private final List<Request> items=new ArrayList<>();private int sequence;public static ReinforcementSavedData get(ServerLevel l){return l.getDataStorage().computeIfAbsent(ReinforcementSavedData::load,ReinforcementSavedData::new,DATA_NAME);}public static ReinforcementSavedData load(CompoundTag tag){ReinforcementSavedData d=new ReinforcementSavedData();d.sequence=tag.getInt("Sequence");ListTag a=tag.getList("Items",Tag.TAG_COMPOUND);for(int i=0;i<a.size();i++)d.items.add(Request.load(a.getCompound(i)));return d;}@Override public CompoundTag save(CompoundTag tag){tag.putInt("Sequence",sequence);ListTag a=new ListTag();for(Request r:items)a.add(r.save());tag.put("Items",a);return tag;}private Request byId(String id){for(Request r:items)if(r.id.equals(id))return r;return null;}private static String s(String v){return v==null?"":v.trim();}private static boolean has(String csv,String u){return Arrays.asList(csv.split(",")).contains(u);}private static String add(String csv,String u){return u==null||u.isBlank()||has(csv,u)?csv:(csv==null||csv.isBlank()?u:csv+","+u);}private static void audit(ServerPlayer p,String a,String id,boolean ok,String why,String after){OperationAuditSavedData.get(p.serverLevel()).record(p,a,id,ok?"ok":"denied",why,"",after);}private static boolean responder(DepartmentPolicy.Identity u,Request r){return (r.targetDepartment.isBlank()||u.department().equals(r.targetDepartment))&&u.level()>=r.minLevel;}
 public Request create(ServerPlayer p,JsonObject o){DepartmentPolicy.Identity u=DepartmentPolicy.identity(p);boolean can=p.hasPermissions(2)||DepartmentPolicy.isFacilityDirector(u.department(),u.position(),u.level())||DepartmentPolicy.isDeptSupervisor(u.department(),u.position(),u.level())||DepartmentPolicy.DEPT_SECURITY.equals(u.department());if(!can){audit(p,"reinforcement_request","",false,"permission","");return null;}Request r=new Request();r.id="reinforcement-"+(++sequence);r.status=OPEN;r.requestDepartment=u.department();r.targetDepartment=DepartmentPolicy.normalizeDepartment(o.has("targetDepartment")?o.get("targetDepartment").getAsString():DepartmentPolicy.DEPT_SECURITY);r.description=s(o.has("description")?o.get("description").getAsString():"");r.location=s(o.has("location")?o.get("location").getAsString():"");r.dangerLevel=s(o.has("dangerLevel")?o.get("dangerLevel").getAsString():"normal");r.neededCount=o.has("neededCount")?Math.max(1,o.get("neededCount").getAsInt()):1;r.minLevel=o.has("minLevel")?Math.max(0,o.get("minLevel").getAsInt()):0;r.requesterUuid=p.getUUID().toString();r.requesterName=p.getScoreboardName();r.createdAt=r.updatedAt=System.currentTimeMillis();items.add(r);setDirty();audit(p,"reinforcement_request",r.id,true,"target="+r.targetDepartment,r.status);return r;} public boolean claim(ServerPlayer p,String id){Request r=byId(id);String u=p.getUUID().toString();boolean ok=r!=null&&OPEN.equals(r.status)&&responder(DepartmentPolicy.identity(p),r);if(ok){r.status=CLAIMED;r.responderUuids=add(r.responderUuids,u);r.updatedAt=System.currentTimeMillis();setDirty();}audit(p,"reinforcement_claim",id,ok,"target_identity",ok?r.status:"");return ok;}public boolean arrived(ServerPlayer p,String id){Request r=byId(id);String u=p.getUUID().toString();boolean ok=r!=null&&CLAIMED.equals(r.status)&&has(r.responderUuids,u);if(ok){r.status=ARRIVED;r.updatedAt=System.currentTimeMillis();setDirty();}audit(p,"reinforcement_arrived",id,ok,"responder",ok?r.status:"");return ok;}public boolean resolve(ServerPlayer p,String id,String reason){Request r=byId(id);DepartmentPolicy.Identity u=DepartmentPolicy.identity(p);boolean ok=r!=null&&(p.hasPermissions(2)||p.getUUID().toString().equals(r.requesterUuid)||DepartmentPolicy.isFacilityDirector(u.department(),u.position(),u.level())||(DepartmentPolicy.isDeptSupervisor(u.department(),u.position(),u.level())&&u.department().equals(r.targetDepartment)));if(ok){r.status=RESOLVED;r.resolution=s(reason);r.updatedAt=System.currentTimeMillis();setDirty();}audit(p,"reinforcement_resolve",id,ok,"requester_or_target_supervisor",ok?r.status:"");return ok;}
 public JsonObject toJsonFor(ServerPlayer v){DepartmentPolicy.Identity u=DepartmentPolicy.identity(v);boolean all=v.hasPermissions(2)||DepartmentPolicy.isFacilityDirector(u.department(),u.position(),u.level());String uuid=v.getUUID().toString();JsonObject root=new JsonObject();JsonArray a=new JsonArray();for(Request r:items)if(all||responder(u,r)||uuid.equals(r.requesterUuid)||has(r.responderUuids,uuid))a.add(r.toJson());root.add("items",a);root.addProperty("skeleton",false);return root;}public static class Request{public String id="",status=OPEN,location="",dangerLevel="",requestDepartment="",targetDepartment="",description="",requesterUuid="",requesterName="",responderUuids="",resolution="";public int neededCount=1,minLevel;public long createdAt,updatedAt;CompoundTag save(){CompoundTag t=new CompoundTag();t.putString("Id",id);t.putString("Status",status);t.putString("Location",location);t.putString("DangerLevel",dangerLevel);t.putString("RequestDepartment",requestDepartment);t.putString("TargetDepartment",targetDepartment);t.putString("Description",description);t.putString("RequesterUuid",requesterUuid);t.putString("RequesterName",requesterName);t.putString("ResponderUuids",responderUuids);t.putString("Resolution",resolution);t.putInt("NeededCount",neededCount);t.putInt("MinLevel",minLevel);t.putLong("CreatedAt",createdAt);t.putLong("UpdatedAt",updatedAt);return t;}static Request load(CompoundTag t){Request r=new Request();r.id=t.getString("Id");r.status=t.getString("Status");r.location=t.getString("Location");r.dangerLevel=t.getString("DangerLevel");r.requestDepartment=t.getString("RequestDepartment");r.targetDepartment=t.getString("TargetDepartment");r.description=t.getString("Description");r.requesterUuid=t.getString("RequesterUuid");r.requesterName=t.getString("RequesterName");r.responderUuids=t.getString("ResponderUuids");r.resolution=t.getString("Resolution");r.neededCount=Math.max(1,t.getInt("NeededCount"));r.minLevel=t.getInt("MinLevel");r.createdAt=t.getLong("CreatedAt");r.updatedAt=t.getLong("UpdatedAt");return r;}JsonObject toJson(){JsonObject o=new JsonObject();o.addProperty("id",id);o.addProperty("status",status);o.addProperty("location",location);o.addProperty("dangerLevel",dangerLevel);o.addProperty("requestDepartment",requestDepartment);o.addProperty("targetDepartment",targetDepartment);o.addProperty("description",description);o.addProperty("requesterName",requesterName);o.addProperty("responderUuids",responderUuids);o.addProperty("neededCount",neededCount);o.addProperty("minLevel",minLevel);o.addProperty("resolution",resolution);o.addProperty("updatedAt",updatedAt);return o;}}}
